      this.ensure(typeof tag === 'string', "tag filter must be a string");
    }
    if (dueBefore !== undefined) {
      this.ensure(!isNaN(new Date(dueBefore).getTime()), "dueBefore filter must be a valid date");
    }
    if (limit !== undefined) {
      this.ensure(typeof limit === 'number' && limit >= 0 && Number.isInteger(limit), "limit must be a non-negative integer");
    }

